 ('mc', 5, 'yunus_dua', 'Yunus’un duası', 'm', 'Hz. Yunus balığın karnında nasıl dua etti?', '“Senden başka ilah yoktur; seni tenzih ederim; ben zalimlerden oldum.”', ['“Beni hemen çıkar, yoksa kızarım.”', '“Bu benim suçum değil.”', 'Hiç dua etmedi'], 'Enbiyâ 21:87: Lâ ilâhe illâ ente sübhâneke innî küntü mine’z-zâlimîn.'),
 ('mc', 5, 'eyyub', 'Sabır örneği', 'm', 'Ağır hastalık ve kayıplara rağmen sabrıyla örnek gösterilen peygamber kimdir?', 'Hz. Eyyûb', ['Hz. Süleyman', 'Hz. Davud', 'Hz. İdris'], 'Sâd 38:44: Biz onu sabırlı bulduk; ne güzel kuldu.'),
 ('mc', 5, 'suleyman_karinca', 'Karınca', 'm', 'Hz. Süleyman hangi hayvanın “Ordusu sizi ezmesin, yuvalarınıza girin” dediğini duyup gülümsedi?', 'Karıncanın', ['Arının', 'Kuşun', 'Atın'], 'Neml 27:18-19.'),
 ('mc', 5, 'hudhud', 'Hüdhüd', 'h', 'Hz. Süleyman’a Sebe melikesinin haberini getiren kuş hangisidir?', 'Hüdhüd', ['Kartal', 'Güvercin', 'Karga'], 'Neml 27:20-22: Hüdhüd, Sebe’den kesin bir haber getirdiğini söyledi.'),
 ('mc', 5, 'davud', 'Hz. Davud', 'm', 'Hz. Davud’a indirilen kitap hangisidir?', 'Zebur', ['Tevrat', 'İncil', 'Suhuf'], 'Nisâ 4:163: Davud’a Zebur’u verdik.'),
 ('mc', 5, 'isa_dogum', 'Hz. İsa’nın doğumu', 'm', 'Âl-i İmrân 59’a göre Hz. İsa’nın babasız yaratılışı kimin yaratılışına benzetilir?', 'Hz. Âdem’in', ['Hz. Nuh’un', 'Hz. İbrahim’in', 'Hz. Yahya’nın'], 'Âl-i İmrân 3:59: Allah katında İsa’nın durumu Âdem’in durumu gibidir.'),
 ('mc', 5, 'isa_besik', 'Beşikte konuşması', 'm', 'Hz. İsa beşikte konuşarak ne dedi?', '“Ben Allah’ın kuluyum; bana kitap verdi ve beni peygamber yaptı.”', ['“Ben Allah’ın oğluyum.”', '“Beni rahat bırakın.”', '“Annem beni tanımıyor.”'], 'Meryem 19:30.'),
 ('mc', 5, 'meryem', 'Hz. Meryem', 'h', 'Kur’an’da adı geçen ve adıyla bir sure bulunan tek kadın kimdir?', 'Hz. Meryem', ['Hz. Hatice', 'Hz. Âsiye', 'Hz. Sâre'], 'Meryem 19. suredir; Âl-i İmrân 3:42’de seçkin kılındığı bildirilir.'),
 ('tf', 5, 'isa_kaldirildi', 'Hz. İsa’nın akıbeti', 'h', 'Nisâ 157-158’e göre Hz. İsa öldürülmedi ve asılmadı; Allah onu kendi katına yükseltti.', True, 'Nisâ 4:157-158.'),
 ('tf', 5, 'zekeriya', 'Hz. Zekeriya', 'm', 'Yaşlılığında Hz. Zekeriya’ya Yahya adında bir oğul müjdelendi.', True, 'Meryem 19:7: Ey Zekeriya, sana Yahya adında bir oğul müjdeliyoruz.'),
 ('sc', 5, 'sc_yunus', 'Hatadan dönmek', 'm', 'Kaan bir hata yaptı ve çok pişman. Hz. Yunus’un kıssası ona ne öğretir?', 'Hatasını kabul edip içtenlikle Allah’a yönelmeyi', ['Hatasını saklamayı', 'Başkasını suçlamayı', 'Ümidini kesmeyi'], 'Yunus “Ben zalimlerden oldum” diyerek hatasını kabul etti; Allah da onu kurtardı (Enbiyâ 21:88).'),
 ('sc', 5, 'sc_karinca', 'Küçük canlılar', 'e', 'Kardeşin yoldaki karıncaları ezmeye çalışıyor. Hz. Süleyman kıssasından ne söylersin?', 'Allah’ın bütün canlılarına özen gösterilmeli', ['Karıncalar önemsizdir', 'Sadece büyük hayvanlar korunur', 'Hiçbir şey söylemem'], 'Büyük bir hükümdar olan Süleyman bile karıncanın sözüne kulak verdi.'),
 ('fb', 5, 'fb_zunnun', 'Balık sahibi', 'h', 'Hz. Yunus, Kur’an’da “balık sahibi” anlamında ___ diye anılır.', 'Zünnûn', ['Zülkarneyn', 'Zülkifl', 'Halîl'], 'Enbiyâ 21:87: Zünnûn’u da an.'),
 ('pr', 5, 'pr_isa_kitap', 'Kitabı', 'e', 'Hz. İsa’ya indirilen kitap ___ dir.', 'İncil', 'Hz. İsa’ya İncil indirilmiştir.'),
 ('mt', 5, 'peygamber_esle', 'Peygamberler ve özellikleri', 'm', 'Peygamberleri özellikleriyle eşleştir:', [('Yunus', 'Balığın karnında dua etti'), ('Eyyûb', 'Hastalığa sabretti'), ('Süleyman', 'Karıncayı duydu'), ('İsa', 'Beşikte konuştu')], 'Her peygamberin kıssası farklı bir ders verir.'),

