 ('mc', 6, 'mc_tekrar_halil', 'Unvan', 'm', '“Halîlullah” hangi peygamberin unvanıdır?', 'Hz. İbrahim', ['Hz. Musa', 'Hz. İsa', 'Hz. Nuh'], 'Halîlullah, Allah’ın dostu demektir.'),
 ('mc', 6, 'mc_tekrar_eyyub', 'Sabır', 'm', 'Sabrıyla tanınan peygamber kimdir?', 'Hz. Eyyûb', ['Hz. Süleyman', 'Hz. Hûd', 'Hz. Sâlih'], 'Hz. Eyyûb sabrın sembolüdür.'),
 ('es', 6, 'es_tekrar_musa_isa', 'Kitaplar', 'm', 'İncil Hz. Musa’ya indirilmiştir.', 'İncil Hz. İsa’ya, Tevrat Hz. Musa’ya indirilmiştir', ['İncil Hz. Davud’a indirilmiştir', 'Hz. Musa’ya kitap indirilmemiştir', 'İncil Hz. Nuh’a indirilmiştir'], 'Tevrat Musa’ya, İncil İsa’ya verildi.'),
 ('es', 6, 'es_tekrar_hudhud', 'Hüdhüd', 'h', 'Hüdhüd kuşu Hz. Musa’ya haber getirdi.', 'Hüdhüd kuşu Hz. Süleyman’a Sebe’den haber getirdi', ['Hüdhüd Hz. Nuh’a zeytin dalı getirdi', 'Hüdhüd Hz. İbrahim’i kurtardı', 'Hüdhüd Hz. Yunus’u balıktan çıkardı'], 'Neml 27:20-22.'),

 # S7 — Ünite Challenge (14)
 ('sc', 7, 'ch_tovbe', 'Tövbe', 'm', 'Arda yanlış bir şey yapıp “Ben zaten kötüyüm, değişemem” diyor. Hz. Âdem ve Hz. Yunus kıssaları ne der?', 'Pişmanlıkla Allah’a yönelen için tövbe kapısı açıktır', ['Bir kez hata yapan değişemez', 'Tövbe yalnızca peygamberlere aittir', 'Hata gizlenmelidir'], 'Âdem ve Yunus hatalarını kabul edip tövbe ettiler; Allah da affetti.'),
 ('sc', 7, 'ch_putlar', 'Akılla sorgulamak', 'h', 'Hz. İbrahim’in büyük putu bırakıp “Ona sorun” demesinin amacı neydi?', 'Kavminin putların aczini düşünüp akıllarını kullanmasını sağlamak', ['Büyük puta tapmalarını istemek', 'Onlarla şaka yapmak', 'Putları korumak'], 'Enbiyâ 21:63-67: Konuşamayan putların ilah olamayacağını fark ettirmek istedi.'),
 ('sc', 7, 'ch_yumusak_dil', 'Kibar söz', 'm', 'Arkadaşın çok kaba bir şekilde konuşuyor. Musa kıssasından hangi ilke işine yarar?', 'Yumuşak bir dille konuşmak; Firavun’a bile yumuşak söz emredildi', ['Ona daha kaba karşılık vermek', 'Onu herkesin önünde rezil etmek', 'Hiç konuşmamak'], 'Tâhâ 20:44.'),
 ('es', 7, 'ch_es_isa_oglu', 'Hz. İsa', 'h', 'Kur’an’a göre Hz. İsa Allah’ın oğludur.', 'Kur’an’a göre Hz. İsa Allah’ın kulu ve peygamberidir', ['Hz. İsa bir melektir', 'Hz. İsa’nın kitabı Tevrat’tır', 'Hz. İsa beşikte hiç konuşmadı'], 'Meryem 19:30: Ben Allah’ın kuluyum.'),
 ('es', 7, 'ch_es_nuh_ogul', 'Nuh’un oğlu', 'm', 'Hz. Nuh’un oğlu gemiye binerek kurtuldu.', 'Hz. Nuh’un oğlu gemiye binmedi ve boğuldu', ['Hz. Nuh’un oğlu gemiyi yaptı', 'Hz. Nuh’un oğlu yoktu', 'Hz. Nuh’un oğlu dağda yaşamaya devam etti'], 'Hûd 11:43: Aralarına dalga girdi ve boğulanlardan oldu.'),
 ('pr', 7, 'ch_pr_yunus_dua', 'Yunus’un duası', 'h', '“Senden başka ilah yoktur, seni tenzih ederim; ben ___ oldum.”', 'zalimlerden', 'Enbiyâ 21:87.'),
 ('pr', 7, 'ch_pr_ahsen', 'En güzel kıssa', 'm', 'Kur’an’da “kıssaların en güzeli” olarak nitelenen kıssa Hz. ___ kıssasıdır.', 'Yusuf', 'Yûsuf 12:3.'),
 ('pr', 7, 'ch_pr_selam', 'Ateş', 'm', '“Ey ateş, İbrahim’e serin ve ___ ol!”', 'selamet', 'Enbiyâ 21:69.'),
 ('mc', 7, 'ch_ulul_azm', 'Ülü’l-azm', 'h', 'Aşağıdakilerden hangisi ülü’l-azm (azim sahibi) peygamberlerden biri değildir?', 'Hz. Yunus', ['Hz. Nuh', 'Hz. Musa', 'Hz. İsa'], 'Ülü’l-azm: Nuh, İbrahim, Musa, İsa ve Hz. Muhammed.'),
 ('mc', 7, 'ch_25', 'Peygamber sayısı', 'm', 'Kur’an’da adı geçen peygamberlerin sayısı kaçtır?', '25', ['5', '12', '124.000'], 'Kur’an’da 25 peygamberin adı geçer; gönderilen peygamberlerin sayısını ise yalnız Allah bilir.'),
 ('mt', 7, 'ch_mt_kavim', 'Kavimler', 'h', 'Peygamberleri gönderildikleri kavimlerle eşleştir:', [('Hûd', 'Âd kavmi'), ('Sâlih', 'Semûd kavmi'), ('Şuayb', 'Medyen halkı'), ('Musa', 'Firavun ve İsrailoğulları')], 'Her peygamber kendi kavmine gönderildi.'),
 ('mt', 7, 'ch_mt_kitap', 'Kitaplar', 'm', 'Kitapları peygamberleriyle eşleştir:', [('Tevrat', 'Hz. Musa'), ('Zebur', 'Hz. Davud'), ('İncil', 'Hz. İsa'), ('Kur’an', 'Hz. Muhammed')], 'Dört büyük ilahi kitap.'),
 ('sc', 7, 'ch_sabir', 'Uzun hastalık', 'm', 'Büyükannen uzun süredir hasta ve zaman zaman umutsuzluğa düşüyor. Ona hangi peygamberin kıssasını anlatırsın?', 'Hz. Eyyûb’un sabrını', ['Firavun’un sonunu', 'Fil ordusunu', 'Kârûn’un hazinelerini'], 'Eyyûb ağır hastalığa sabretti ve Allah’a dua etti; Allah da ona şifa verdi (Enbiyâ 21:83-84).'),
